{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 자전거 등록시스템 구축 협조요청에 대해 구청이 특별한 사유 없이 협조하지 않아도 되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제3조제7항에 따르면, 시장은 자전거 등록에 필요한 계획 수립·시행과 등록 시스템 구축을 위해 노력하여야 하며, 자치구의 협조가 필요한 경우 구청장은 특별한 사유가 없으면 협조요청에 따라야 한다. 따라서 구청이 특별한 사유 없이 협조하지 않아도 되는 것은 아니다.",
          "b_ids": "자전거:제3조제7항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
